    R.NG = rate < 1 ? Math.min(6000, Math.max(600, Math.ceil(Math.log(0.02) / Math.log(rate)))) : 600;
    R.NX = 60; R.NY = 40; R.grid = [];
    for (j = 0; j < R.NY; j++) for (i = 0; i < R.NX; i++) {
      for (x = [-X + (i + 0.5) * 2 * X / R.NX, -Y + (j + 0.5) * 2 * Y / R.NY], t = 0; t < R.NG; t++) { x = stepf(S, x); n = Math.abs(x[0]) + Math.abs(x[1]); if (n < 1e-4 * sc || !(n < 1e3 * sc)) break; }
      k = n < 0.05 * sc ? 1 : n < 1e3 * sc && R.rCL < 1 ? 2 : 0; R.grid.push(k); cnt += k === 1 ? 1 : 0; und += k === 2 ? 1 : 0; // 1 converged, 0 not converging, 2 undecided (still decaying?) within the budget
    }
    R.frac = cnt / (R.NX * R.NY); R.und = und / (R.NX * R.NY);
  }

  function draw(R) {
    var L = 54, T = 12, pw = 534, ph = 339, X = R.X, Y = R.Y, i, j, k, v, s, cw = pw / R.NX, ch = ph / R.NY;
    function sx(v) { return (L + (v + X) / (2 * X) * pw).toFixed(1); }
    function sy(v) { return (T + (Y - v) / (2 * Y) * ph).toFixed(1); }
    function pl(p, col, w, dash, fill) { return '<polyline points="' + p.map(function (q) { return sx(q[0]) + ',' + sy(q[1]); }).join(' ') + '" fill="' + (fill || 'none') + '" stroke="' + col + '" stroke-width="' + w + '"' + (dash ? ' stroke-dasharray="' + dash + '"' : '') + '/>'; }
    s = '<defs><clipPath id="nl-clip"><rect x="' + L + '" y="' + T + '" width="' + pw + '" height="' + ph + '"/></clipPath></defs>';
    for (j = 0; j < R.NY; j++) for (i = 0; i < R.NX; i = k) { // shading, merged into runs
      for (k = i; k < R.NX && R.grid[j * R.NX + k] === R.grid[j * R.NX + i]; k++);
      s += '<rect x="' + (L + i * cw).toFixed(1) + '" y="' + (T + (R.NY - 1 - j) * ch).toFixed(1) + '" width="' + ((k - i) * cw + 0.5).toFixed(1) + '" height="' + (ch + 0.5).toFixed(1) + '" fill="' + ['#fdeceb', '#e3f2e5', '#eeeeee'][R.grid[j * R.NX + i]] + '"/>';
    }
    var dx = nice(X / 2.5), dy = nice(Y / 2.5);
    for (v = -Math.floor(X / dx) * dx; v <= X + 1e-9; v += dx) s += '<line x1="' + sx(v) + '" y1="' + T + '" x2="' + sx(v) + '" y2="' + (T + ph) + '" stroke="' + (Math.abs(v) < 1e-9 ? '#bbb' : '#e8e8e8') + '"/><text x="' + sx(v) + '" y="' + (T + ph + 15) + '" font-size="11" fill="#666" text-anchor="middle">' + (+v.toFixed(4)) + '</text>';
    for (v = -Math.floor(Y / dy) * dy; v <= Y + 1e-9; v += dy) s += '<line x1="' + L + '" y1="' + sy(v) + '" x2="' + (L + pw) + '" y2="' + sy(v) + '" stroke="' + (Math.abs(v) < 1e-9 ? '#bbb' : '#e8e8e8') + '"/><text x="' + (L - 6) + '" y="' + (+sy(v) + 4) + '" font-size="11" fill="#666" text-anchor="end">' + (+v.toFixed(4)) + '</text>';
    s += '<g clip-path="url(#nl-clip)">';
    if (R.cert && R.mode === 'local') R.S.W0.forEach(function (w) { // box lines w.x = +-delta
      var nn = w[0] * w[0] + w[1] * w[1], e = [-w[1] * 4 * (X + Y) / Math.sqrt(nn), w[0] * 4 * (X + Y) / Math.sqrt(nn)];
      [-1, 1].forEach(function (sg) { var p = [sg * R.d * w[0] / nn, sg * R.d * w[1] / nn]; s += pl([[p[0] - e[0], p[1] - e[1]], [p[0] + e[0], p[1] + e[1]]], '#e67e22', 1.5, '6 4'); });
    });
    if (R.cert) { // certified ellipse (local) or level sets of V (global): x = L^-T u, |u| = r
      var Lc = chol(R.P);
      (R.mode === 'local' ? [1] : [1, 0.4, 0.12]).forEach(function (f, idx) {
        var p = [], r = Math.sqrt(f * R.cmax);
        for (k = 0; k <= 72; k++) { var x1 = r * Math.sin(k * Math.PI / 36) / Lc[1][1]; p.push([(r * Math.cos(k * Math.PI / 36) - Lc[1][0] * x1) / Lc[0][0], x1]); }
        s += R.mode === 'local' ? pl(p, '#1565c0', 2, '', 'rgba(21,101,192,0.15)') : pl(p, '#1565c0', idx ? 1 : 1.8, idx ? '4 3' : '');
      });
    }
    R.traj.forEach(function (tj) { var col = tj.inside ? '#1565c0' : '#7b1fa2'; s += pl(tj.pts, col, 1.3) + '<circle cx="' + sx(tj.pts[0][0]) + '" cy="' + sy(tj.pts[0][1]) + '" r="3" fill="' + col + '"/>'; });
    s += '</g><rect x="' + L + '" y="' + T + '" width="' + pw + '" height="' + ph + '" fill="none" stroke="#999"/>';
    s += '<text x="' + (L + pw / 2) + '" y="387" font-size="12" fill="#333" text-anchor="middle">x&#8321; (angle)</text><text x="14" y="' + (T + ph / 2) + '" font-size="12" fill="#333" text-anchor="middle" transform="rotate(-90 14 ' + (T + ph / 2) + ')">x&#8322; (rate)</text>';
    el('nl-svg').innerHTML = s;
  }

  function info(R) {
    var ok = '<strong style="color:#2e7d32;">', bad = '<strong style="color:#c62828;">', h, n = R.n;
    function ph(s) { // what phase I computed: a signed value, not a proof of infeasibility
      return isNaN(s) ? 'phase I (trace P = 1) stopped without a result' : 'phase I (trace P = 1, minimise s with &lambda;<sub>max</sub>(&#8499;) &le; s and &lambda;<sub>min</sub>(P) &ge; &minus;s; s &lt; 0 is a certificate) ends at s = ' + fmt(s) + '; the page accepts only s &lt; ' + fmt(-PH1);
    }
    h = 'Open loop &rho;(A) = ' + fmt(R.rOL) + (R.rOL > 1 + 1e-9 ? ' (unstable)' : R.rOL > 1 - 1e-9 ? ' (near the stability boundary)' : ' (stable)') + ' &middot; linearised loop &rho;(A + BW&#8321;W&#8320;) = ' + fmt(R.rCL) + ' &middot; |u| &le; ' + fmt(R.umax, 2) + '<br>';
    var cert = R.cert ? 'P = [' + fmt(R.P[0][0]) + ', ' + fmt(R.P[0][1]) + '; ' + fmt(R.P[0][1]) + ', ' + fmt(R.P[1][1]) + '], &lambda; = (' + fmt(R.lam[0]) + ', ' + fmt(R.lam[1]) + '); Jacobi re-check: &lambda;<sub>max</sub>(&#8499;) = ' + fmt(R.eM) + ' &lt; 0' : '';
    if (R.mode === 'global') {
      if (R.cert) h += ok + 'Numerically certified globally</strong> (the sector [0, 1] holds for all v): ' + cert + '. V = x&#7488;Px decreases along every trajectory; dashed: level sets of V.<br>';
      else h += bad + 'Not certified</strong> by the global sector: ' + ph(R.s) + '. ' + (R.corner >= 1 - 1e-9
        ? 'The sector contains the laws w = diag(&kappa;)v, &kappa; &isin; {0,1}&sup2;, and the worst, &kappa; = (' + R.cornerK.join(', ') + ')' + (R.cornerK[0] + R.cornerK[1] ? (R.cornerK[0] * R.cornerK[1] ? ', the linearised loop,' : ',') : ', the controller switched off,') + ' has &rho; = ' + fmt(R.corner) + (R.corner > 1 + 1e-9 ? ' &gt; 1 (beyond rounding error): an unstable member of the sector, so no certificate can exist.<br>' : ', equal to 1 up to 10<sup>&minus;9</sup>: too close to the stability boundary to decide numerically.<br>')
        : 'The four laws w = diag(&kappa;)v, &kappa; &isin; {0,1}&sup2;, are stable (worst &rho; = ' + fmt(R.corner) + ')' + (isNaN(R.s) ? '.<br>'
          : R.s > 0 ? ', yet s &gt; 0: numerically (not a proof), no quadratic V with diagonal multipliers works for every nonlinearity in the sector.<br>'
          : R.s < -PH1 ? '; phase I met the margin, but the eigenvalue re-check rejected its point (a numerical failure, not infeasibility).<br>'
          : '; the phase-I point meets the LMIs only with a margin below the required one, so no certificate is claimed.<br>'));
    } else if (R.cert) {
      var r = R.S.W0.map(function (w) { return fmt(Math.sqrt(quad(R.Pi, w)), 2); });
      h += 'Bisection: &delta;<sub>max</sub> = ' + fmt(R.dmax, 2) + (R.dmax >= 40 ? ' (search cap)' : '') + '; golden section picks &delta; = ' + fmt(R.d, 2) + ', i.e. the sector [' + fmt(R.al) + ', 1] on |v<sub>i</sub>| &le; &delta;.<br>' + ok + 'Numerically certified</strong>: ' + cert + ', &lambda;<sub>min</sub>(containment) = ' + fmt(R.eC) + ' &ge; 0, trace P = ' + fmt(R.P[0][0] + R.P[1][1]) + '. Every x&#8320; in the blue ellipse converges to 0; on it max|v&#8321;| = ' + r[0] + ', max|v&#8322;| = ' + r[1] + ' (&le; &delta;).<br>';
    } else h += bad + 'No local certificate</strong>: ' + (R.rCL >= 1 - 1e-9 ? 'the linearised loop has &rho; = ' + fmt(R.rCL) + (R.rCL > 1 + 1e-9 ? ' &gt; 1 (beyond rounding error), and w = v lies in every sector [&alpha;, 1], so no certificate can exist.' : ', equal to 1 up to 10<sup>&minus;9</sup>: too close to the stability boundary to decide numerically.')
      : R.tb && !R.tb.ok ? 'none found with the required margin, even for the box |v<sub>i</sub>| &le; 0.02: ' + ph(R.tb.s) + '. The linearised loop is Schur stable (&rho; = ' + fmt(R.rCL, 5) + '), so certificates exist for small enough boxes; here one would need a smaller box or a smaller margin.'
      : 'phase I is feasible for boxes up to &delta; = ' + fmt(R.dmax, 2) + ', but the minimisation of trace P or the eigenvalue re-check returned no certificate (a numerical failure, not infeasibility).') + '<br>';
    h += '<span style="color:#555;">Simulation (evidence, not proof): ' + (R.cert ? n[1] + '/' + n[0] + ' starts on the ' + (R.mode === 'local' ? 'ellipse' : 'outer level set') + ' reached the proximity threshold; sampled V(x<sub>t+1</sub>)/V(x<sub>t</sub>) max = ' + fmt(R.vr) + ' over evaluated steps' + (n[2] ? '; ' + n[3] + '/' + n[2] + ' starts outside reached the proximity threshold. ' : '. ') : n[3] + '/' + n[2] + ' starts reached the proximity threshold. ');
    el('nl-info').innerHTML = h + Math.round(100 * R.frac) + '% of the grid reached the proximity threshold' + (R.und ? ', ' + (R.und < 0.01 ? '&lt;1' : Math.round(100 * R.und)) + '% undecided after ' + R.NG + ' steps (grey)' : '') + ' (' + R.ms + ' ms).</span>';
  }

  var timer = null;
  function schedule() {
    [['nl-a', 1], ['nl-b', 1], ['nl-w0', 1], ['nl-w1', 2]].forEach(function (p) { el(p[0] + '-v').textContent = (+el(p[0]).value).toFixed(p[1]); });
    if (timer) clearTimeout(timer);
    timer = setTimeout(compute, 60);
  }
  ['nl-a', 'nl-b', 'nl-w0', 'nl-w1'].forEach(function (id) { el(id).addEventListener('input', schedule); });
  el('nl-mode').addEventListener('change', schedule);
  function setAll(v) { ['nl-a', 'nl-b', 'nl-w0', 'nl-w1', 'nl-mode'].forEach(function (id, i) { el(id).value = v[i]; }); schedule(); }
  el('nl-preset').addEventListener('click', function () { setAll([-1, 1, 1, 0.2, 'global']); });
  el('nl-reset').addEventListener('click', function () { setAll([2, 1, 1, 1, 'local']); });
  schedule();
})();
